 * The instant-runoff counting itself, independent of how it is reported.
 */

/**
 * Runs the count described by `{ candidates, ballots }` and returns
 * `{ rounds, winner }`, where `rounds` is an array of
 * `{ counts: Map<name, votes>, exhausted, eliminated }` (one per round
 * counted, in order, `eliminated` being the eliminated name or `null` for a
 * round that ended the election) and `winner` is the winning name or `null`.
 */
export function countRounds({ candidates, ballots }) {
  let remaining = new Set(candidates)
  const rounds = []
  const history = [] // history[roundIndex] = Map<name, votes> for that round
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const c of remaining) counts.set(c, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((n) => remaining.has(n))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
      }
    }

    let activeTotal = 0
    for (const v of counts.values()) activeTotal += v

    history.push(counts)

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = null
      break
    }

    let majorityWinner = null
    for (const [name, votes] of counts) {
      if (votes * 2 > activeTotal) {
        majorityWinner = name
        break
      }
    }

    if (majorityWinner !== null) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = majorityWinner
      break
    }

    const eliminated = pickElimination(remaining, counts, history)
    rounds.push({ counts, exhausted, eliminated })
    remaining.delete(eliminated)
  }

  return { rounds, winner }
}

function pickElimination(remaining, counts, history) {
  let minVotes = Infinity
  for (const c of remaining) {
    const v = counts.get(c)
    if (v < minVotes) minVotes = v
  }
  let tied = [...remaining].filter((c) => counts.get(c) === minVotes)

  while (tied.length > 1) {
    let foundRound = -1
    for (let r = 0; r < history.length; r++) {
      const roundCounts = history[r]
      const vals = tied.map((c) => roundCounts.get(c))
      if (!vals.every((v) => v === vals[0])) {
        foundRound = r
        break
      }
    }
    if (foundRound === -1) {
      tied.sort()
      return tied[tied.length - 1]
    }
    const roundCounts = history[foundRound]
    const vals = tied.map((c) => roundCounts.get(c))
    const minVal = Math.min(...vals)
    tied = tied.filter((c, i) => vals[i] === minVal)
  }

  return tied[0]
}
"}

